   section.innerHTML=`${depBanner()}<section class="slot-head"><div><h2 class="section-title">Tasks & Times</h2><div class="hint">Manage each task and all of its time slots together. Expand a task to view or edit its times.</div></div><div class="slot-actions"><input id="task-search" placeholder="Search tasks"><button class="secondary" id="copy-task-times">Copy Task Times</button><button class="primary" id="addt">Add Task</button></div></section><div id="tasktime-msg" class="message"></div><div id="tasks"><div class="loading">Loading tasks and times…</div></div>`;
